     1→import { useState, type FormEvent } from 'react';
     2→import { useNavigate } from 'react-router-dom';
     3→import { useAuth } from '../hooks/useAuth';
     4→
     5→export default function LoginPage() {
     6→  const [username, setUsername] = useState('');
     7→  const [password, setPassword] = useState('');
     8→  const [error, setError] = useState('');
     9→  const [loading, setLoading] = useState(false);
    10→  const { login } = useAuth();
    11→  const navigate = useNavigate();
    12→
    13→  const handleSubmit = async (e: FormEvent) => {
    14→    e.preventDefault();
    15→    setError('');
    16→    setLoading(true);
    17→    try {
    18→      await login(username, password);
    19→      navigate('/');
    20→    } catch (err: any) {
    21→      setError(err.message);
    22→    } finally {
    23→      setLoading(false);
    24→    }
    25→  };
    26→
    27→  return (
    28→    <div className="min-h-screen flex items-center justify-center">
    29→      <div className="bg-white rounded-xl shadow-lg p-8 w-full max-w-sm">
    30→        <img src="/bosarsa.jpeg" alt="BOS-ARSA" className="h-20 mx-auto mb-4 rounded" />
    31→        <h1 className="text-2xl font-bold text-[#1e3a5f] text-center mb-1">BOS-ARSA Log</h1>
    32→        <p className="text-sm text-gray-500 text-center mb-6">Im Sinne der Sicherheit</p>
    33→        <form onSubmit={handleSubmit} className="space-y-4">
    34→          <div>
    35→            <label className="block text-sm font-medium text-gray-700 mb-1">Benutzername</label>
    36→            <input
    37→              type="text"
    38→              value={username}
    39→              onChange={e => setUsername(e.target.value)}
    40→              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
    41→              required
    42→              autoFocus
    43→            />
    44→          </div>
    45→          <div>
    46→            <label className="block text-sm font-medium text-gray-700 mb-1">Passwort</label>
    47→            <input
    48→              type="password"
    49→              value={password}
    50→              onChange={e => setPassword(e.target.value)}
    51→              className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
    52→              required
    53→            />
    54→          </div>
    55→          {error && <p className="text-red-600 text-sm">{error}</p>}
    56→          <button
    57→            type="submit"
    58→            disabled={loading}
    59→            className="w-full bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white font-medium py-2 rounded-lg disabled:opacity-50"
    60→          >
    61→            {loading ? 'Anmelden...' : 'Anmelden'}
    62→          </button>
    63→        </form>
    64→      </div>
    65→    </div>
    66→  );
    67→}
