     1→import { useState, useEffect } from 'react';
     2→import { Link, useNavigate } from 'react-router-dom';
     3→import { useAuth } from '../hooks/useAuth';
     4→import { apiFetch } from '../services/api';
     5→import {
     6→  Chart as ChartJS,
     7→  CategoryScale, LinearScale, BarElement, PointElement, LineElement,
     8→  Title, Tooltip, Legend, Filler,
     9→} from 'chart.js';
    10→import { Bar, Line } from 'react-chartjs-2';
    11→
    12→ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, LineElement, Title, Tooltip, Legend, Filler);
    13→
    14→const EXERCISE_TYPES = [
    15→  'Krisenkommunikationsübung',
    16→  'Notfunkübung',
    17→  'Feldtag',
    18→  'Relaisfunktest',
    19→];
    20→
    21→interface ExerciseSummary {
    22→  id: string;
    23→  name: string | null;
    24→  date: string;
    25→  participant_count: number;
    26→  report_count: number;
    27→}
    28→
    29→function getQuarter(date: string): number {
    30→  const month = new Date(date + 'T00:00:00').getMonth();
    31→  return Math.floor(month / 3) + 1;
    32→}
    33→
    34→export default function DashboardPage() {
    35→  const { admin } = useAuth();
    36→  const navigate = useNavigate();
    37→  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
    38→  const [loading, setLoading] = useState(true);
    39→  const [showCreate, setShowCreate] = useState(false);
    40→  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
    41→  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
    42→  const [creating, setCreating] = useState(false);
    43→
    44→  useEffect(() => {
    45→    apiFetch('/api/v1/exercises')
    46→      .then(data => setExercises(data))
    47→      .catch(() => {})
    48→      .finally(() => setLoading(false));
    49→  }, []);
    50→
    51→  const formatDate = (d: string) => {
    52→    const date = new Date(d + 'T00:00:00');
    53→    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
    54→  };
    55→
    56→  // Compute nearest exercise to today
    57→  const today = new Date().toISOString().split('T')[0];
    58→  const nearestId = exercises.length > 0
    59→    ? exercises.reduce((closest, e) => {
    60→        const dCur = Math.abs(new Date(e.date).getTime() - new Date(today).getTime());
    61→        const dBest = Math.abs(new Date(closest.date).getTime() - new Date(today).getTime());
    62→        return dCur < dBest ? e : closest;
    63→      }, exercises[0]).id
    64→    : null;
    65→
    66→  // Compute quarterly and yearly totals
    67→  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
    68→  let yearParticipants = 0;
    69→  let yearReports = 0;
    70→
    71→  for (const ex of exercises) {
    72→    const q = getQuarter(ex.date);
    73→    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    74→    quarterTotals[q].participants += ex.participant_count;
    75→    quarterTotals[q].reports += ex.report_count;
    76→    yearParticipants += ex.participant_count;
    77→    yearReports += ex.report_count;
    78→  }
    79→
    80→  // Build rows with quarter subtotals inserted
    81→  const buildRows = () => {
    82→    const rows: { type: 'exercise' | 'quarter' | 'year'; data?: ExerciseSummary; quarter?: number; participants?: number; reports?: number }[] = [];
    83→    let lastQuarter = 0;
    84→
    85→    for (let i = 0; i < exercises.length; i++) {
    86→      const ex = exercises[i];
    87→      const q = getQuarter(ex.date);
    88→      const nextEx = exercises[i + 1];
    89→      const nextQ = nextEx ? getQuarter(nextEx.date) : 0;
    90→
    91→      rows.push({ type: 'exercise', data: ex });
    92→
    93→      // Insert quarter subtotal when quarter changes or at last exercise
    94→      if (q !== nextQ && quarterTotals[q]) {
    95→        rows.push({ type: 'quarter', quarter: q, ...quarterTotals[q] });
    96→        lastQuarter = q;
    97→      }
    98→    }
    99→
   100→    // Yearly total
   101→    if (exercises.length > 0) {
   102→      rows.push({ type: 'year', participants: yearParticipants, reports: yearReports });
   103→    }
   104→
   105→    return rows;
   106→  };
   107→
   108→  const QUARTER_LABELS: Record<number, string> = { 1: 'Q1 (Jan-Mär)', 2: 'Q2 (Apr-Jun)', 3: 'Q3 (Jul-Sep)', 4: 'Q4 (Okt-Dez)' };
   109→
   110→  return (
   111→    <div>
   112→      <div className="flex items-center justify-between mb-4 sm:mb-6 gap-2">
   113→        <div className="min-w-0">
   114→          <h1 className="text-xl sm:text-2xl font-bold text-[#1e3a5f]">Gesamtübersicht</h1>
   115→          <p className="text-xs sm:text-sm text-gray-500">Willkommen, {admin?.username}</p>
   116→        </div>
   117→        {admin?.role === 'admin' && (
   118→          <button
   119→            onClick={() => setShowCreate(v => !v)}
   120→            className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-4 py-2 rounded-lg text-sm font-medium"
   121→          >
   122→            + Neue Übung
   123→          </button>
   124→        )}
   125→      </div>
   126→
   127→      {showCreate && (
   128→        <div className="bg-white rounded-xl shadow p-4 mb-6">
   129→          <h2 className="text-sm font-semibold text-[#1e3a5f] mb-3">Neue Übung anlegen</h2>
   130→          <div className="flex items-end gap-3 flex-wrap">
   131→            <div className="w-full sm:w-auto">
   132→              <label className="block text-xs text-gray-500 mb-1">Datum</label>
   133→              <input
   134→                type="date"
   135→                value={newDate}
   136→                onChange={e => setNewDate(e.target.value)}
   137→                className="border border-gray-300 rounded px-2 py-1.5 text-sm w-full sm:w-auto focus:outline-none focus:ring-2 focus:ring-blue-500"
   138→              />
   139→            </div>
   140→            <div className="flex-1 min-w-0 w-full sm:w-auto">
   141→              <label className="block text-xs text-gray-500 mb-1">Typ / Name</label>
   142→              <div className="flex gap-2">
   143→                <select
   144→                  value={EXERCISE_TYPES.includes(newName) ? newName : ''}
   145→                  onChange={e => setNewName(e.target.value)}
   146→                  className="border border-gray-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
   147→                >
   148→                  {EXERCISE_TYPES.map(t => (
   149→                    <option key={t} value={t}>{t}</option>
   150→                  ))}
   151→                  <option value="">Eigener Name...</option>
   152→                </select>
   153→                {!EXERCISE_TYPES.includes(newName) && (
   154→                  <input
   155→                    type="text"
   156→                    value={newName}
   157→                    onChange={e => setNewName(e.target.value)}
   158→                    placeholder="Name der Übung"
   159→                    className="border border-gray-300 rounded px-2 py-1.5 text-sm flex-1 focus:outline-none focus:ring-2 focus:ring-blue-500"
   160→                    autoFocus
   161→                  />
   162→                )}
   163→              </div>
   164→            </div>
   165→            <button
   166→              disabled={creating || !newDate || !newName}
   167→              onClick={async () => {
   168→                setCreating(true);
   169→                try {
   170→                  const ex = await apiFetch('/api/v1/exercises', {
   171→                    method: 'POST',
   172→                    body: JSON.stringify({ date: newDate, name: newName }),
   173→                  });
   174→                  navigate(`/exercises/${ex.id}/setup`);
   175→                } catch {
   176→                } finally {
   177→                  setCreating(false);
   178→                }
   179→              }}
   180→              className="bg-green-600 hover:bg-green-700 text-white px-4 py-1.5 rounded text-sm font-medium disabled:opacity-50"
   181→            >
   182→              {creating ? 'Erstellen...' : 'Erstellen'}
   183→            </button>
   184→            <button
   185→              onClick={() => setShowCreate(false)}
   186→              className="text-gray-500 text-sm hover:text-gray-700"
   187→            >
   188→              Abbrechen
   189→            </button>
   190→          </div>
   191→        </div>
   192→      )}
   193→
   194→      {/* Summary cards */}
   195→      {!loading && exercises.length > 0 && (
   196→        <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 mb-4 sm:mb-6">
   197→          <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   198→            <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{exercises.length}</div>
   199→            <div className="text-sm text-gray-500">Übungen</div>
   200→          </div>
   201→          <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   202→            <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{yearParticipants}</div>
   203→            <div className="text-sm text-gray-500">Teilnehmer gesamt</div>
   204→          </div>
   205→          <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   206→            <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{yearReports}</div>
   207→            <div className="text-sm text-gray-500">Rapporte gesamt</div>
   208→          </div>
   209→          <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   210→            <div className="text-2xl sm:text-3xl font-bold text-gray-600">
   211→              {exercises.length > 0 ? Math.round(yearParticipants / exercises.filter(e => e.participant_count > 0).length || 1) : 0}
   212→            </div>
   213→            <div className="text-sm text-gray-500">Teilnehmer/Übung</div>
   214→          </div>
   215→        </div>
   216→      )}
   217→
   218→      {/* Trend chart */}
   219→      {!loading && exercises.length > 0 && (
   220→        <div className="bg-white rounded-xl shadow p-4 mb-6">
   221→          <h2 className="text-sm font-semibold text-[#1e3a5f] mb-3">BOS-ARSA Übungen {new Date().getFullYear()}</h2>
   222→          <div className="h-48 sm:h-[300px]">
   223→            <Bar
   224→              data={{
   225→                labels: exercises.map(e => {
   226→                  const d = new Date(e.date + 'T00:00:00');
   227→                  return d.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit' });
   228→                }),
   229→                datasets: [
   230→                  {
   231→                    label: 'Teilnehmer',
   232→                    data: exercises.map(e => e.participant_count),
   233→                    backgroundColor: '#1e3a5f',
   234→                  },
   235→                  {
   236→                    label: 'Rapporte',
   237→                    data: exercises.map(e => e.report_count),
   238→                    backgroundColor: '#c8102e',
   239→                  },
   240→                ],
   241→              }}
   242→              options={{
   243→                responsive: true,
   244→                maintainAspectRatio: false,
   245→                plugins: {
   246→                  legend: { position: 'bottom' },
   247→                },
   248→                scales: {
   249→                  y: { beginAtZero: true },
   250→                },
   251→              }}
   252→            />
   253→          </div>
   254→        </div>
   255→      )}
   256→
   257→      {loading ? (
   258→        <p className="text-gray-500">Laden...</p>
   259→      ) : exercises.length === 0 ? (
   260→        <p className="text-gray-500">Noch keine Übungen erstellt.</p>
   261→      ) : (
   262→        <div className="bg-white rounded-xl shadow overflow-x-auto">
   263→          <table className="w-full text-xs sm:text-sm min-w-[480px]">
   264→            <thead className="bg-[#1e3a5f] text-white">
   265→              <tr>
   266→                <th className="px-2 sm:px-4 py-2 text-left">Datum</th>
   267→                <th className="px-2 sm:px-4 py-2 text-left hidden sm:table-cell">Name</th>
   268→                <th className="px-2 sm:px-4 py-2 text-right">Teiln.</th>
   269→                <th className="px-2 sm:px-4 py-2 text-right">Rapp.</th>
   270→                <th className="px-2 sm:px-4 py-2"></th>
   271→              </tr>
   272→            </thead>
   273→            <tbody>
   274→              {buildRows().map((row, idx) => {
   275→                if (row.type === 'exercise') {
   276→                  const ex = row.data!;
   277→                  const isNearest = ex.id === nearestId;
   278→                  return (
   279→                    <tr key={ex.id} className={`border-t ${isNearest ? 'bg-blue-100 font-medium' : 'hover:bg-blue-50'}`}>
   280→                      <td className="px-2 sm:px-4 py-2 font-mono text-xs sm:text-sm">
   281→                        {formatDate(ex.date)}
   282→                        {isNearest && <span className="ml-1 sm:ml-2 text-[10px] sm:text-xs bg-[#c8102e] text-white px-1 sm:px-1.5 py-0.5 rounded">Aktuell</span>}
   283→                      </td>
   284→                      <td className="px-2 sm:px-4 py-2 text-gray-700 hidden sm:table-cell">{ex.name || '—'}</td>
   285→                      <td className="px-2 sm:px-4 py-2 text-right">{ex.participant_count}</td>
   286→                      <td className="px-2 sm:px-4 py-2 text-right">{ex.report_count}</td>
   287→                      <td className="px-2 sm:px-4 py-2 text-right space-x-1 sm:space-x-2">
