   290→                        </Link>
   291→                        <Link to={`/exercises/${ex.id}/reports`} className="text-blue-600 hover:underline text-xs hidden sm:inline">
   292→                          Auswertung
   293→                        </Link>
   294→                      </td>
   295→                    </tr>
   296→                  );
   297→                }
   298→                if (row.type === 'quarter') {
   299→                  return (
   300→                    <tr key={`q${row.quarter}`} className="bg-blue-50 font-semibold border-t-2 border-blue-200">
