     9→  onReportUpdated: (report: any) => void;
    10→  onReportDeleted: (reportId: number) => void;
    11→}
    12→
    13→interface EntryForm {
    14→  callsign: string;
    15→  operator: any;
    16→  rapport: string;
    17→  notes: string;
    18→}
    19→
    20→export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    21→  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
    22→  const [bezirke, setBezirke] = useState<any[]>([]);
    23→  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
    24→  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
    25→  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
    26→  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
    27→  const [addRepBl, setAddRepBl] = useState<string | null>(null);
    28→  const [newRepName, setNewRepName] = useState('');
    29→  const [newRepFreq, setNewRepFreq] = useState('');
    30→  const [newRepCallsign, setNewRepCallsign] = useState('');
    31→  const [editingId, setEditingId] = useState<number | null>(null);
    32→  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '' });
    33→
    34→  useEffect(() => {
    35→    Promise.all([
    36→      apiFetch('/api/v1/reference/bundeslaender'),
    37→      apiFetch('/api/v1/reference/bezirke'),
    38→      apiFetch('/api/v1/repeaters'),
    39→      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    40→    ]).then(([bl, bz, allReps, exReps]) => {
    41→      setBundeslaender(bl);
    42→      setBezirke(bz);
    43→      const linked = allReps.filter((r: any) => r.is_linked);
    44→      setLinkedRepeaters(linked);
    45→      // Initialize per-BL defaults: first linked in that BL, else first overall
    46→      const defaults: Record<string, number> = {};
    47→      const ops: Record<string, string> = {};
    48→      for (const b of bl) {
    49→        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
    50→        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
    51→        defaults[b.code] = repId;
    52→        // Load existing OP callsign from exercise_repeaters
    53→        const exRep = exReps.find((er: any) => er.repeater_id === repId);
    54→        ops[b.code] = exRep?.operator_callsign || '';
    55→      }
    56→      setBlRepSelection(defaults);
    57→      setBlOpCallsigns(ops);
    58→    }).catch(() => {});
    59→  }, [exerciseId]);
    60→
    61→  const saveOpCallsign = async (blCode: string, val: string) => {
    62→    const repId = blRepSelection[blCode];
    63→    if (!repId) return;
    64→    try {
    65→      // Ensure exercise_repeater exists, then update
    66→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
    67→        method: 'POST',
    68→        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
    69→      });
    70→    } catch {
    71→      // Already exists, just patch
    72→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
    73→        method: 'PATCH',
    74→        body: JSON.stringify({ operator_callsign: val || null }),
    75→      });
    76→    }
    77→  };
    78→
    79→  const addRepeater = async (blCode: string) => {
    80→    if (!newRepName && !newRepFreq) return;
    81→    const name = newRepName || `Direkte ${newRepFreq}`;
    82→    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    83→    try {
    84→      const rep = await apiFetch('/api/v1/repeaters', {
    85→        method: 'POST',
    86→        body: JSON.stringify({
    87→          short_name: name,
    88→          site_name: name,
    89→          frequency_mhz: freq,
    90→          callsign: newRepCallsign || null,
    91→          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
    92→          type: 'repeater',
    93→          bundesland_code: blCode,
    94→        }),
    95→      });
    96→      setLinkedRepeaters(prev => [...prev, rep]);
    97→      setNewRepName('');
    98→      setNewRepFreq('');
    99→      setNewRepCallsign('');
   100→      setAddRepBl(null);
   101→    } catch {}
   102→  };
   103→
   104→  const toggleBl = (code: string) => {
   105→    setCollapsedBl(prev => {
   106→      const next = new Set(prev);
   107→      if (next.has(code)) next.delete(code); else next.add(code);
   108→      return next;
   109→    });
   110→  };
   111→
   112→  const parseRapport = (raw: string) => {
   113→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
   114→    if (!match) return { readability: null, strength: null, db_over_s9: null };
   115→    return {
   116→      readability: parseInt(match[1]),
   117→      strength: parseInt(match[2]),
   118→      db_over_s9: match[3]?.trim() || null,
   119→    };
   120→  };
   121→
   122→  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
   123→    try {
   124→      if (!repeaterId) return;
   125→      const operator = await getOrCreateOperator(form.callsign, form.operator);
   126→      if (!operator) return;
   127→
   128→      // Set operator's bezirk_code to match the row they were entered in
   129→      if (bezirkCode && bezirkCode !== '??') {
   130→        apiFetch(`/api/v1/operators/${operator.id}`, {
   131→          method: 'PATCH',
   132→          body: JSON.stringify({ bezirk_code: bezirkCode }),
   133→        }).catch(() => {});
   134→      }
   135→
   136→      const parsed = parseRapport(form.rapport);
   137→
   138→      try {
   139→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   140→          method: 'POST',
   141→          body: JSON.stringify({
   142→            operator_id: operator.id,
   143→            repeater_id: repeaterId,
   144→            ...parsed,
   145→            notes: form.notes || null,
   146→          }),
   147→        });
   148→        // Force bezirk_code on report so it shows in the correct row immediately
   149→        if (bezirkCode && bezirkCode !== '??') report.bezirk_code = bezirkCode;
   150→        onReportCreated(report);
   151→      } catch (err: any) {
   152→        if (err.message?.includes('existiert')) {
   153→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   154→          if (existing) {
   155→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   156→              method: 'PATCH',
   157→              body: JSON.stringify({ ...parsed, notes: form.notes || null }),
   158→            });
   159→            if (bezirkCode && bezirkCode !== '??') updated.bezirk_code = bezirkCode;
   160→            onReportUpdated(updated);
   161→          }
   162→        }
   163→      }
   164→    } catch {
   165→    }
   166→  };
   167→
   168→  const handleEdit = (report: any) => {
   169→    setEditingId(report.id);
   170→    setEditForm({
   171→      callsign: report.callsign,
   172→      operator: { id: report.operator_id, callsign: report.callsign },
   173→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   174→      notes: report.notes || '',
   175→    });
   176→  };
   177→
   178→  const handleUpdate = async () => {
   179→    if (!editingId) return;
   180→    const parsed = parseRapport(editForm.rapport);
   181→    try {
   182→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   183→        method: 'PATCH',
   184→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null }),
   185→      });
   186→      onReportUpdated(updated);
   187→      setEditingId(null);
   188→    } catch {}
   189→  };
   190→
   191→  const handleDelete = async (reportId: number) => {
   192→    if (!confirm('Rapport löschen?')) return;
   193→    try {
   194→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   195→      onReportDeleted(reportId);
   196→    } catch {}
   197→  };
   198→
   199→  return (
   200→    <div className="space-y-2">
   201→      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
   202→        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
   203→        const defaultRepId = blRepSelection[bl.code] || 0;
   204→        // Match reports by repeater's Bundesland (where the report was entered)
   205→        const blReports = reports.filter(r => r.repeater_bundesland_code === bl.code);
   206→        const isCollapsed = collapsedBl.has(bl.code);
   207→        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;
   208→
   209→        return (
   210→          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
   211→            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
   212→              <div
   213→                onClick={() => toggleBl(bl.code)}
   214→                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
   215→              >
   216→                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   217→                <span className="font-medium text-xs sm:text-sm truncate">{bl.name}</span>
   218→                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
   219→              </div>
   220→              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
   221→                <button
   222→                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
   223→                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
   224→                >
   225→                  + Umsetzer
   226→                </button>
   227→                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
   228→                <input
   229→                  type="text"
   230→                  value={blOpCallsigns[bl.code] || ''}
   231→                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
   232→                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
   233→                  placeholder="Rufz."
   234→                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   235→                />
   236→              </div>
   237→            </div>
   238→
   239→            {!isCollapsed && (
   240→              <div>
   241→                {addRepBl === bl.code && (
   242→                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
   243→                    <input
   244→                      type="text"
   245→                      value={newRepName}
   246→                      onChange={e => setNewRepName(e.target.value)}
   247→                      placeholder="Name"
   248→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
   249→                      autoFocus
   250→                    />
   251→                    <input
   252→                      type="text"
   253→                      value={newRepFreq}
   254→                      onChange={e => setNewRepFreq(e.target.value)}
   255→                      placeholder="MHz"
   256→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   257→                    />
   258→                    <input
   259→                      type="text"
   260→                      value={newRepCallsign}
   261→                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   262→                      placeholder="Rufz."
   263→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   264→                    />
   265→                    <button
   266→                      onClick={() => addRepeater(bl.code)}
   267→                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   268→                    >
   269→                      OK
   270→                    </button>
   271→                    <button
   272→                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
   273→                      className="text-gray-400 hover:text-gray-600 text-xs"
   274→                    >
   275→                      Abbrechen
   276→                    </button>
   277→                  </div>
   278→                )}
   279→                <div className="divide-y divide-gray-100">
   280→                  {blBezirke.map(bz => {
   281→                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   282→                    return (
   283→                      <BezirkRow
   284→                        key={bz.code}
   285→                        bezirk={bz}
   286→                        reports={bzReports}
   287→                        linkedRepeaters={linkedRepeaters}
   288→                        defaultRepeaterId={defaultRepId}
   289→                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
   290→                        onEdit={handleEdit}
   291→                        onDelete={handleDelete}
   292→                        editingId={editingId}
   293→                        editForm={editForm}
   294→                        onEditChange={setEditForm}
   295→                        onEditSave={handleUpdate}
   296→                        onEditCancel={() => setEditingId(null)}
   297→                      />
   298→                    );
   299→                  })}
   300→                  {/* Reports without matching bezirk — shown directly as list items */}
   301→                  {(() => {
   302→                    const bzCodes = new Set(blBezirke.map(b => b.code));
   303→                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   304→                    if (unassigned.length === 0) return null;
   305→                    return (
   306→                      <div className="px-3 py-1.5">
   307→                        <table className="w-full text-xs mb-1">
   308→                          <tbody>
   309→                            {unassigned.map((r, idx) => (
   310→                              <tr key={r.id} className="hover:bg-blue-50 group">
   311→                                {editingId === r.id ? (
   312→                                  <td colSpan={5} className="py-0.5">
   313→                                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1">
   314→                                      <span className="font-mono font-medium">{r.callsign}</span>
   315→                                      <input value={editForm.rapport} onChange={e => setEditForm({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" autoFocus />
   316→                                      <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   317→                                      <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   318→                                      <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   319→                                    </div>
   320→                                  </td>
   321→                                ) : (
   322→                                  <>
   323→                                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   324→                                    <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => handleEdit(r)}>{r.callsign}</td>
   325→                                    <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   326→                                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   327→                                    </td>
   328→                                    <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   329→                                    <td className="py-0.5 w-4">
   330→                                      <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   331→                                    </td>
   332→                                  </>
   333→                                )}
   334→                              </tr>
   335→                            ))}
   336→                          </tbody>
   337→                        </table>
   338→                      </div>
   339→                    );
   340→                  })()}
   341→                </div>
   342→              </div>
   343→            )}
   344→          </div>
   345→        );
   346→      })}
   347→    </div>
   348→  );
   349→}
   350→
   351→interface BezirkRowProps {
   352→  bezirk: any;
   353→  reports: any[];
   354→  linkedRepeaters: any[];
   355→  defaultRepeaterId: number;
   356→  onSubmit: (repeaterId: number, form: EntryForm) => void;
   357→  onEdit: (report: any) => void;
   358→  onDelete: (id: number) => void;
   359→  editingId: number | null;
   360→  editForm: EntryForm;
   361→  onEditChange: (form: EntryForm) => void;
   362→  onEditSave: () => void;
   363→  onEditCancel: () => void;
   364→}
   365→
   366→function BezirkRow({ bezirk, reports, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, editingId, editForm, onEditChange, onEditSave, onEditCancel }: BezirkRowProps) {
   367→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '' });
   368→  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
   369→  const callsignRef = useRef<CallsignInputRef>(null);
   370→
   371→  useEffect(() => {
   372→    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
   373→  }, [defaultRepeaterId]);
   374→
   375→  const handleSubmit = (e: FormEvent) => {
   376→    e.preventDefault();
   377→    if (!form.callsign && !form.operator) return;
   378→    if (!repeaterId) return;
   379→    onSubmit(repeaterId, form);
   380→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '' });
   381→    setTimeout(() => callsignRef.current?.focus(), 50);
   382→  };
   383→
   384→  return (
   385→    <div className="px-2 sm:px-3 py-1.5">
   386→      {bezirk.code !== '??' && (
   387→        <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   388→          <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   389→            {bezirk.code}
   390→          </span>
   391→          <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   392→          {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   393→        </div>
   394→      )}
   395→
   396→      {reports.length > 0 && (
   397→        <table className="w-full text-xs mb-1">
   398→          <tbody>
   399→            {reports.map((r, idx) => (
   400→              <tr key={r.id} className="hover:bg-blue-50 group">
   401→                {editingId === r.id ? (
   402→                  <td colSpan={5} className="py-0.5">
   403→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap">
   404→                      <span className="font-mono font-medium">{r.callsign}</span>
   405→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   406→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   407→                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
   408→                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
   409→                    </div>
   410→                  </td>
   411→                ) : (
   412→                  <>
   413→                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   414→                    <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => onEdit(r)}>{r.callsign}</td>
   415→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   416→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   417→                    </td>
   418→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   419→                    <td className="py-0.5 w-4">
   420→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   421→                    </td>
   422→                  </>
   423→                )}
   424→              </tr>
   425→            ))}
   426→          </tbody>
   427→        </table>
   428→      )}
   429→
   430→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   431→        {linkedRepeaters.length > 0 && (
   432→          <select
   433→            value={repeaterId || ''}
   434→            onChange={e => setRepeaterId(parseInt(e.target.value))}
   435→            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
   436→          >
   437→            {linkedRepeaters.map(r => (
   438→              <option key={r.id} value={r.id}>
   439→                {r.site_name || r.short_name}
   440→              </option>
   441→            ))}
   442→          </select>
   443→        )}
   444→        <CallsignInput
   445→          ref={callsignRef}
   446→          value={form.callsign}
   447→          onChange={v => setForm(f => ({ ...f, callsign: v }))}
   448→          onSelect={op => setForm(f => ({ ...f, operator: op, callsign: op.callsign }))}
   449→          className="w-24 sm:w-28"
   450→        />
   451→        <input
   452→          type="text"
   453→          value={form.rapport}
   454→          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
   455→          placeholder="5/9"
   456→          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   457→          onKeyDown={e => {
   458→            if (e.altKey && e.key >= '1' && e.key <= '9') {
   459→              e.preventDefault();
   460→              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
