const sundays = [];
const d = new Date('2026-01-04T00:00:00'); // first Sunday of 2026
while (d.getFullYear() === 2026) {
  const dateStr = d.toISOString().slice(0, 10);
  if (!existingDates.has(dateStr)) {
    sundays.push(dateStr);
  }
  d.setDate(d.getDate() + 7);
}

console.log('Sundays to create:', sundays.length);

// Repeater IDs from existing config
const repeaterIds = [265, 269, 281];

const insertExercise = db.prepare('INSERT INTO exercises (id, date, name, oe_link_enabled) VALUES (?, ?, ?, 1)');
const insertRepeater = db.prepare('INSERT INTO exercise_repeaters (exercise_id, repeater_id) VALUES (?, ?)');

const tx = db.transaction(() => {
  for (const date of sundays) {
    const id = crypto.randomUUID();
    const name = 'Krisenkommunikationsübung ' + date;
    insertExercise.run(id, date, name);
    for (const rid of repeaterIds) {
      insertRepeater.run(id, rid);
    }
  }
});

tx();
console.log('Created', sundays.length, 'exercises');

// Verify
const total = db.prepare('SELECT COUNT(*) as c FROM exercises').get();
const krisenTotal = db.prepare(\\\"SELECT COUNT(*) as c FROM exercises WHERE name LIKE '%Krisenkommunikations%'\\\").get();
console.log('Total exercises:', total.c);
console.log('Krisenkommunikationsübungen:', krisenTotal.c);

db.close();
